True def transform(grid):
    height, width = len(grid), len(grid[0])
    background = grid[0][0]
    marker = next(value for row in grid for value in row if value != background)
    output = [row[:] for row in grid]

    for r, row in enumerate(grid):
        positions = [c for c, value in enumerate(row) if value == marker]
        if len(positions) >= 2:
            for c in range(min(positions) + 1, max(positions)):
                if grid[r][c] == background:
                    output[r][c] = 3

    for c in range(width):
        positions = [r for r in range(height) if grid[r][c] == marker]
        if len(positions) >= 2:
            for r in range(min(positions) + 1, max(positions)):
                if grid[r][c] == background:
                    output[r][c] = 3

    return output
